import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.OLpNgP4A.js";const m=JSON.parse('{"title":"DevOps & Infrastructure Master Guide","description":"Comprehensive overview of culture and flow, containerization, CI/CD automation, infrastructure as code, SRE, and AI-driven operations with explicit book and chapter mapping","frontmatter":{"title":"DevOps & Infrastructure Master Guide","description":"Comprehensive overview of culture and flow, containerization, CI/CD automation, infrastructure as code, SRE, and AI-driven operations with explicit book and chapter mapping"},"headers":[],"relativePath":"devops-infrastructure/index.md","filePath":"devops-infrastructure/index.md","lastUpdated":1789221836000}'),s={name:"devops-infrastructure/index.md"};function n(o,e,d,c,l,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<div class="se-hero"><div class="se-hero-badge">DevOps Curriculum 2026</div><h1>DevOps &amp; Infrastructure Master Guide</h1><p class="se-hero-subtitle">Master the principles of lean value streams, container orchestration, CI/CD automation pipelines, infrastructure as code, and site reliability engineering.</p></div><hr><h2 id="_1-culture-flow" tabindex="-1">1. Culture &amp; Flow <a class="header-anchor" href="#_1-culture-flow" aria-label="Permalink to &quot;1. Culture &amp; Flow&quot;">​</a></h2><p>Establish lean management principles, optimize value streams, and cultivate high-performance organizational feedback loops across engineering teams (<em>The DevOps Handbook, Chapters 1 &amp; 4</em>).</p><div class="se-principles-grid"><div class="se-principle-card"><h3>The Three Ways</h3><p>Understand the foundational principles of flow, feedback, and continuous experimentation that underpin modern DevOps culture.</p></div><div class="se-principle-card"><h3>Value Stream Mapping</h3><p>Identify bottlenecks, reduce lead times, and visualize the flow of work from code commit to production deployment.</p></div></div><hr><h2 id="_2-containers-docker" tabindex="-1">2. Containers &amp; Docker <a class="header-anchor" href="#_2-containers-docker" aria-label="Permalink to &quot;2. Containers &amp; Docker&quot;">​</a></h2><p>Master containerization fundamentals, image layering, runtime isolation, and multi-container orchestration patterns (<em>Introduction to Docker, Chapter 1; Docker Deep Dive, Chapters 2 &amp; 5</em>).</p><div class="testing-stack"><div class="testing-card se-card-blue"><div class="card-header"><h3>Container Fundamentals</h3><span class="tagline">Runtime Isolation</span></div><div class="card-body"><p><strong>Expectation:</strong> Build lightweight container images, manage layer caching, and configure isolated network namespaces and storage volumes.</p></div></div><div class="testing-card se-card-green"><div class="card-header"><h3>Image Architecture</h3><span class="tagline">Best Practices</span></div><div class="card-body"><p><strong>Expectation:</strong> Write secure, multi-stage Dockerfiles that minimize attack surface and reduce overall image size for production environments.</p></div></div></div><hr><h2 id="_3-ci-cd-workflows" tabindex="-1">3. CI/CD &amp; Workflows <a class="header-anchor" href="#_3-ci-cd-workflows" aria-label="Permalink to &quot;3. CI/CD &amp; Workflows&quot;">​</a></h2><p>Automate building, testing, and deployment pipelines using advanced version control strategies and continuous integration frameworks (<em>The DevOps Handbook, Chapter 9; GitHub Actions Guides</em>).</p><div class="testing-stack"><div class="testing-card se-card-orange"><div class="card-header"><h3>Automated Pipelines</h3><span class="tagline">Continuous Integration</span></div><div class="card-body"><p><strong>Expectation:</strong> Construct robust GitHub Actions workflows to execute automated testing, code linting, and rapid artifact promotion.</p></div></div><div class="testing-card se-card-ts"><div class="card-header"><h3>Advanced Git Workflows</h3><span class="tagline">Version Control</span></div><div class="card-body"><p><strong>Expectation:</strong> Enforce clean branching strategies, pull request gating, and automated tagging to streamline collaborative feature delivery.</p></div></div></div><hr><h2 id="_4-infrastructure-sre" tabindex="-1">4. Infrastructure &amp; SRE <a class="header-anchor" href="#_4-infrastructure-sre" aria-label="Permalink to &quot;4. Infrastructure &amp; SRE&quot;">​</a></h2><p>Treat infrastructure as software through automated provisioning and scale production reliability using disciplined SRE methodologies (<em>Infrastructure as Code, Chapters 1 &amp; 3; Site Reliability Engineering, Chapters 3 &amp; 5</em>).</p><div class="testing-stack"><div class="testing-card se-card-py"><div class="card-header"><h3>Infrastructure as Code</h3><span class="tagline">Cloud Provisioning</span></div><div class="card-body"><p><strong>Expectation:</strong> Implement declarative provisioning patterns, immutability, and version-controlled infrastructure templates for cloud environments.</p></div></div><div class="testing-card se-card-blue"><div class="card-header"><h3>Site Reliability Engineering</h3><span class="tagline">Production Scale</span></div><div class="card-body"><p><strong>Expectation:</strong> Manage service level objectives (SLOs), error budgets, and reduce operational toil through automation.</p></div></div></div><hr><h2 id="_5-ai-operations" tabindex="-1">5. AI &amp; Operations <a class="header-anchor" href="#_5-ai-operations" aria-label="Permalink to &quot;5. AI &amp; Operations&quot;">​</a></h2><p>Integrate artificial intelligence tools and automated machine learning workflows into modern DevOps lifecycles (<em>AI &amp; DevOps, Chapter 1</em>).</p><div class="testing-stack"><div class="testing-card se-card-green"><div class="card-header"><h3>AI-Driven Operations</h3><span class="tagline">Smart Automation</span></div><div class="card-body"><p><strong>Expectation:</strong> Leverage AI assistants and predictive analytics for anomaly detection, automated log analysis, and incident triage.</p></div></div></div><hr><h2 id="_6-system-foundations-architecture" tabindex="-1">6. System Foundations &amp; Architecture <a class="header-anchor" href="#_6-system-foundations-architecture" aria-label="Permalink to &quot;6. System Foundations &amp; Architecture&quot;">​</a></h2><p>Understand low-level computing mechanics, hardware interfaces, and core computer architecture (<em>Introduction to Computing Systems, Chapters 1 &amp; 2</em>).</p><div class="testing-stack"><div class="testing-card se-card-orange"><div class="card-header"><h3>Computing Systems</h3><span class="tagline">Low-Level Mechanics</span></div><div class="card-body"><p><strong>Expectation:</strong> Comprehend the underlying machine model, instruction set architecture, and software-to-hardware execution stack.</p></div></div></div><hr><h2 id="key-literature-sources" tabindex="-1">Key Literature &amp; Sources <a class="header-anchor" href="#key-literature-sources" aria-label="Permalink to &quot;Key Literature &amp; Sources&quot;">​</a></h2><div class="se-refs-container"><div class="se-ref-item"><strong>The DevOps Handbook</strong> by Gene Kim et al. Lean management, value streams, and CI/CD (Chapters 1, 4, &amp; 9). </div><div class="se-ref-item"><strong>Introduction to Docker</strong> by Bobby Iliev. Containerization basics and runtime mechanics (Chapter 1). </div><div class="se-ref-item"><strong>Docker Deep Dive</strong> by Nigel Poulton. Advanced container architectures and networking (Chapters 2 &amp; 5). </div><div class="se-ref-item"><strong>Infrastructure as Code</strong> by Kief Morris. Cloud provisioning and declarative configuration (Chapters 1 &amp; 3). </div><div class="se-ref-item"><strong>Site Reliability Engineering</strong> by Betsy Beyer et al. Reliability metrics and error budgets (Chapters 3 &amp; 5). </div><div class="se-ref-item"><strong>AI &amp; DevOps</strong> by Devops Shack. AI integration in deployment pipelines (Chapter 1). </div><div class="se-ref-item"><strong>Introduction to Computing Systems</strong> by Yale Patt &amp; Sanjay Patel. Computer architecture and low-level mechanics (Chapters 1 &amp; 2). </div></div>',28)])])}const v=a(s,[["render",n]]);export{m as __pageData,v as default};
